class Solution:
    def sortArray(self, nums: List[int]) -> List[int]:
        def sift_down(i: int, n: int) -> None:  # 在 nums[0..n-1] 这个最大堆里让 nums[i] 下沉
            while True:
                big, l, r = i, 2 * i + 1, 2 * i + 2
                if l < n and nums[l] > nums[big]:
                    big = l
                if r < n and nums[r] > nums[big]:
                    big = r
                if big == i:
                    return
                nums[i], nums[big] = nums[big], nums[i]
                i = big
        n = len(nums)
        for i in range(n // 2 - 1, -1, -1):     # 建最大堆：从最后一个非叶子往前下沉
            sift_down(i, n)
        for end in range(n - 1, 0, -1):
            nums[0], nums[end] = nums[end], nums[0]     # 堆顶（最大）换到末尾
            sift_down(0, end)                   # 剩下的 end 个数重新调成堆
        return nums

