      const k = R.int(1, 4), nums = R.arr(R.int(k - 1, k + 3), 1, 20), adds = R.arr(R.int(3, 6), 1, 20);
      return { args: { k, nums, adds }, note: `k = ${k}, nums = ${R.fmt(nums)}，依次 add ${adds.join("、")}` };
    })(R); return { args: r.args, note: r.note }; }
